    a = [row[:] for row in grid]
    h, w = len(a), len(a[0])
    for r in range(h):
        cs = [c for c in range(w) if a[r][c] == 1]
        if cs:
            for c in range(min(cs), max(cs) + 1):
                if a[r][c] != 1: a[r][c] = 2
    for c in range(w):
        rs = [r for r in range(h) if a[r][c] == 1]
        if rs:
            for r in range(min(rs), max(rs) + 1):
                if a[r][c] != 1: a[r][c] = 2
    return a
